import java.io.*;public class Main {    public static void main(String[] args) throws Exception{        File f = new File("/safe/" + readLine());        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(f)));        String line = reader.readLine();        while (line != null)            {                System.out.println(line);                 line = reader.readLine();             }     }    public static String readLine() throws IOException{        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        return br.readLine();    } }